        /// <summary>
        ///   <para>
        ///     Releases resources a subclass owns. Called once by Dispose(), after the native proxy has been destroyed,
        ///     so no callback can still be running - override this instead of hiding Dispose().
        ///   </para>
        /// </summary>
        protected virtual void DisposeManaged() { }

        /// <summary>
        ///   <para>
        ///     Destroys the native proxy and releases the self-handle, then calls DisposeManaged() so a subclass can
        ///     release its own resources. Never call this while the listener is still installed; calling it more than
        ///     once, or from more than one thread, is harmless.
        ///   </para>
        /// </summary>
        public void Dispose()
        {
            var proxy = Interlocked.Exchange(ref _proxy, 0);
            if (proxy == 0)
                return;
            try
            {
                // The native proxy goes first, so no further callback can arrive into state
                // DisposeManaged() is about to release
                _base = default;
                Jolt.PInvoke.CharacterContactListener_DestroyProxy(proxy);
                if (_self.IsAllocated)
                    _self.Free();
                _self = default;
            }
            finally
            {
                DisposeManaged();
            }
        }
